import "dotenv/config";
import { defineConfig } from "prisma/config";

const user = process.env.POSTGRES_USER || 'app_user';
const password = process.env.POSTGRES_PASSWORD || 'app_secure_password';
const port = process.env.POSTGRES_PORT || '5432';
const db = process.env.POSTGRES_DB || 'ecommerce_db';

const databaseUrl = `postgresql://${user}:${password}@localhost:${port}/${db}?schema=public&connection_limit=20&pool_timeout=10`;

export default defineConfig({
  schema: "prisma/schema.prisma",
  migrations: {
    path: "prisma/migrations",
  },
  datasource: {
    url: databaseUrl,
  },
});
